function firstNameFromEmail(email) {
    var local = String(email).split("@")[0];
    var raw = local.split(".")[0].replace(/[^a-zA-Z0-9]/g, "");
    if (!raw) return "";
    return raw.charAt(0).toUpperCase() + raw.slice(1);
}

var agent = ZT.getVariableValue("agent", "");
ZT.setFormData("agent_first_name", firstNameFromEmail(agent));

