// Build a clean, human-readable session summary for the email.
// Zingtree's ##TRANSCRIPT## renders raw node titles plus styled button spans that
// are hard to read. This rebuilds the agent's captured answers into simple
// "Question: Answer" rows, adds the scenario and the recommended actions (with
// their links), and stores transforms.summary_html, which the Email node renders.
// The set of questions is fixed, so the layout is always the same.

const g = (name) => ZT.getVariableValue(name, "");

const QA = [
  ["Has the performance recovered?", "mob_recovered"],
  ["Does the alert contain an Advice field?", "mob_has_advice"],
  ["Which Advice field does the alert have?", "mob_advice"],
  ["Is a seasonality effect occurring?", "seasonality_effect"],
  ["Is the merchant getting new or a different type of traffic?", "new_or_different_traffic"],
  ["Is the merchant initiating more retries?", "merchant_is_initiating_more_retries"],
  ["Is the decline coming from a specific issuer and/or BIN?", "issuer_bin"],
  ["Is this a one-off issue or platform-wide?", "oneoff_platform"],
  ["Are ongoing experiments influencing performance?", "experiments"],
  ["Is the underperformance statistically significant?", "pcr_significant"],
  ["How is the Payment Conversion Rate moving?", "pcr"],
  ["Has the merchant adopted Protect with Machine Learning?", "protect_ml_adopted"],
  ["Is Protect premium enabled?", "protect_premium"],
  ["Using the latest version of Protect (ML based)?", "fraud_ml"],
  ["Using Adyen as the main risk/fraud provider?", "fraud_main_provider"],
  ["Implemented all risk/fraud recommendations?", "fraud_recs"],
  ["Large and persistent difference in fraud rate?", "fraud_diff"],
  ["Dominant decline reason", "decline_reason"],
  ["Is Account Updater+ and NTO enabled?", "au_nto"],
  ["Is the issue related to a specific product?", "no_specific_product"]
];

const scenario = () => {
  if (g("mob_recovered") || g("mob_has_advice") || g("mob_advice")) return "Performance dropped over time (internal MOB alert)";
  if (g("seasonality_effect") || g("new_or_different_traffic") || g("merchant_is_initiating_more_retries") || g("issuer_bin") || g("oneoff_platform") || g("experiments")) return "Performance dropped over time (noticed while reviewing)";
  if (g("pcr_significant") || g("pcr")) return "Adyen Uplift - Payment Conversion Rate underperformance";
  if (g("protect_premium")) return "Adyen Uplift - Fraud rate underperformance";
  if (g("decline_reason")) return "Performance compared to a competitor";
  return "";
};

let rows = "";
QA.forEach(([question, name]) => {
  const v = g(name);
  if (v !== "") {
    rows += '<tr><td style="padding:4px 14px 4px 0;color:#6b7280;vertical-align:top;">' + question + '</td>'
          + '<td style="padding:4px 0;font-weight:600;">' + v + '</td></tr>';
  }
});

const agent = g("agent");
const sc = scenario();

let html = '<div style="font-family:Arial,Helvetica,sans-serif;color:#111827;">';
html += '<h2 style="margin:0 0 4px;font-size:20px;">Adyen Underperformance Playbook - Session Summary</h2>';
if (agent) html += '<p style="margin:0 0 2px;color:#6b7280;font-size:13px;">Agent: ' + agent + '</p>';
if (sc) html += '<p style="margin:0 0 12px;"><strong>Scenario:</strong> ' + sc + '</p>';
if (rows) {
  html += '<h3 style="margin:16px 0 6px;font-size:16px;">Responses</h3>';
  html += '<table style="border-collapse:collapse;font-size:14px;">' + rows + '</table>';
}
html += '<h3 style="margin:18px 0 6px;font-size:16px;">Recommended actions</h3>';
html += (transforms.outcome_html || "<p>No specific recommendation was captured.</p>");
html += '</div>';

ZT.setTransformData("summary_html", html);

